(322, 'Women Development Cell', '', '<div class=\"women-developement-cell\">\n<div class=\"row g-3\"><!-- Image 1 -->\n<div class=\"col-12 col-md-6 col-lg-4\"><a href=\"https://mnwc.edu.in/uploads/Film-Festival-on-Women-Oriented-Movies_-scaled-420x250.jpg\" data-lightbox=\"womendevp\" data-title=\"International Women\'s Day Celebration\"> <img class=\"img-fluid img-thumbnail\" title=\"International Women\'s Day Celebration\" src=\"https://mnwc.edu.in/uploads/Film-Festival-on-Women-Oriented-Movies_-scaled-420x250.jpg\" alt=\"International Women\'s Day Celebration\" /> </a></div>\n<!-- Image 2 -->\n<div class=\"col-12 col-md-6 col-lg-4\"><a href=\"https://mnwc.edu.in/uploads/International-Womens-Day-Celebration_-scaled-420x250.jpg\" data-lightbox=\"womendevp\" data-title=\"International Women\'s Day Celebration\"> <img class=\"img-fluid img-thumbnail\" title=\"International Women\'s Day Celebration\" src=\"https://mnwc.edu.in/uploads/International-Womens-Day-Celebration_-scaled-420x250.jpg\" alt=\"International Women\'s Day Celebration\" /> </a></div>\n<!-- Image 3 -->\n<div class=\"col-12 col-md-6 col-lg-4\"><a href=\"https://mnwc.edu.in/uploads/Panel-Discussion-on-Women-In-Sports_-Opportunities-and-Challenges-Genderlogue-420x250.jpg\" data-lightbox=\"womendevp\" data-title=\"Panel Discussion on Women In Sports: Opportunities and Challenges - Genderlogue\"> <img class=\"img-fluid img-thumbnail\" title=\"Panel Discussion on Women In Sports: Opportunities and Challenges - Genderlogue\" src=\"https://mnwc.edu.in/uploads/Panel-Discussion-on-Women-In-Sports_-Opportunities-and-Challenges-Genderlogue-420x250.jpg\" alt=\"Panel Discussion on Women In Sports: Opportunities and Challenges - Genderlogue\" /> </a></div>\n<!-- Image 4 -->\n<div class=\"col-12 col-md-6 col-lg-4\"><a href=\"https://mnwc.edu.in/uploads/Play-Performance-on-_Bas-Itni-si-Baat-hai_-by-MAVA-420x250.jpg\" data-lightbox=\"womendevp\" data-title=\"Play Performance on Bas Itni si Baat hai by MAVA\"> <img class=\"img-fluid img-thumbnail\" title=\"Play Performance on Bas Itni si Baat hai by MAVA\" src=\"https://mnwc.edu.in/uploads/Play-Performance-on-_Bas-Itni-si-Baat-hai_-by-MAVA-420x250.jpg\" alt=\"Play Performance on Bas Itni si Baat hai by MAVA\" /> </a></div>\n<!-- Image 5 -->\n<div class=\"col-12 col-md-6 col-lg-4\"><a href=\"https://mnwc.edu.in/uploads/Workshop-on-the-art-of-origami_-420x250.jpg\" data-lightbox=\"womendevp\" data-title=\"Workshop on the art of origami\"> <img class=\"img-fluid img-thumbnail\" title=\"Workshop on the art of origami\" src=\"https://mnwc.edu.in/uploads/Workshop-on-the-art-of-origami_-420x250.jpg\" alt=\"Workshop on the art of origami\" /> </a></div>\n</div>\n</div>', 'same_window', 'women-development-cell', 'user_defined', 0, '', '', '', 'Women Development Cell', 1, NULL, 1, '', '1970-01-02', 2),
(323, 'Alumni MNAA', '', '<div class=\"container page-content\">\n<p class=\"inner-para text-justify\"><strong>Maniben Nanavati Women&rsquo;s College (MNAA)</strong> is registered under <strong>Societies Registration Act, 1860 &ndash; Registration No. 1387/2019 on 29th July 2019.</strong></p>\n<h5 class=\"section-title mt-3\">Objectives:</h5>\n<ul class=\"unstyled-ul\">\n<li>To act as a bridge between College and Alumni.</li>\n<li>To extend help to alumni for getting placement and motivating alumni to extend help to current students.</li>\n<li>To inspire alumni to sponsor for College Activities / Programmes / Events.</li>\n<li>To conduct Alumni Meet.</li>\n<li>To reinstall the sense of social awareness and responsibility that had been inculcated in them by the college.</li>\n<li>To increase college networking through alumni.</li>\n<li>To motivate alumni to become member of MNAA.</li>\n</ul>\n</div>\n<div class=\"col-12 col-lg-4\"><a class=\"btn-pdf w-100\" href=\"https://mnwc.edu.in/uploads/6PTA-2016.pdf\" target=\"_blank\" rel=\"noopener\"><span class=\"btn-text\">PTA 2016-17</span></a></div>', 'same_window', 'alumni-mnaa', 'user_defined', 0, 'Alumni MNAA', '', '', 'Alumni MNAA', 1, NULL, 1, '', '1970-01-02', 2),
