(334, 'Exam Rules', '', '<div class=\"container page-content\">\n<div class=\"table-responsive\">\n<table class=\"table table-bordered table-striped table-head-style\">\n<thead class=\"table-dark\">\n<tr>\n<th class=\"serial-width\">Sr. No.</th>\n<th style=\"text-align: left;\">Title</th>\n<th>Document</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td class=\"text-center\">1</td>\n<td>Exam Rules &ndash; UG</td>\n<td class=\"text-center\"><a class=\"view-btn\" href=\"https://mnwc.edu.in/uploads/1UG-EXAMINATION-RULES.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">View </a></td>\n</tr>\n<tr>\n<td class=\"text-center\">2</td>\n<td>Exam Rules &ndash; PG</td>\n<td class=\"text-center\"><a class=\"view-btn\" href=\"https://mnwc.edu.in/uploads/2PG-EXAM-RULES1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">View </a></td>\n</tr>\n</tbody>\n</table>\n</div>\n</div>', 'same_window', 'exam-rules', 'user_defined', 0, 'Exam Rules', '', '', 'Exam Rules', 1, NULL, 1, '', '1970-01-02', 279),
(335, 'Programs Outcomes', '', '<div class=\"row g-4\"><!-- Bachelor of Arts -->\n<div class=\"col-md-4\">\n<div class=\"program-card h-100\">\n<h4 class=\"text-danger\">Bachelor of Arts</h4>\n<h5 class=\"program-head\">Program Outcome</h5>\n<ul>\n<li><a href=\"https://mnwc.edu.in/uploads/Bachelor-of-Arts-B.A.pdf\" target=\"_blank\" rel=\"noopener\">Bachelor of Arts </a></li>\n</ul>\n<h5 class=\"program-head\">Specific Outcome</h5>\n<ul>\n<li><a href=\"https://mnwc.edu.in/uploads/1Programme-Specific-Outcome-PSO-B.A-Gujarati.pdf\" target=\"_blank\" rel=\"noopener\">B.A &ndash; Gujarati </a></li>\n<li><a href=\"https://mnwc.edu.in/uploads/2Programme-Specific-Outcome-PSO-B.A-Psychology.pdf\" target=\"_blank\" rel=\"noopener\">B.A &ndash; Psychology </a></li>\n<li><a href=\"https://mnwc.edu.in/uploads/3Programme-Specific-Outcome-PSO-B.A-Sociology.pdf\" target=\"_blank\" rel=\"noopener\">B.A &ndash; Sociology </a></li>\n<li><a href=\"https://mnwc.edu.in/uploads/4Programme-Specific-Outcome-PSO-B.A-Economics.pdf\" target=\"_blank\" rel=\"noopener\">B.A &ndash; Economics </a></li>\n<li><a href=\"https://mnwc.edu.in/uploads/5Programme-Specific-Outcome-PSO-B.A-English-Literature.pdf\" target=\"_blank\" rel=\"noopener\">B.A &ndash; English Literature </a></li>\n</ul>\n</div>\n</div>\n<!-- Bachelor of Commerce -->\n<div class=\"col-md-4\">\n<div class=\"program-card h-100\">\n<h4 class=\"text-danger\">Bachelor of Commerce</h4>\n<h5 class=\"program-head\">Program Outcome</h5>\n<ul>\n<li><a href=\"https://mnwc.edu.in/uploads/Bachelors-of-Commerce-B.Com_.pdf\" target=\"_blank\" rel=\"noopener\">Bachelor of Commerce </a></li>\n</ul>\n<h5 class=\"program-head\">Specific Outcome</h5>\n<ul>\n<li><a href=\"https://mnwc.edu.in/uploads/1Programme-Specific-Outcome-PSO-B.Com-Office-Management-Secretarial-Practice.pdf\" target=\"_blank\" rel=\"noopener\">B.Com &ndash; Office Management <br />&amp; Secretarial Practice </a></li>\n<li><a href=\"https://mnwc.edu.in/uploads/2Programme-Specific-Outcome-PSO-B.Com-Travel-Tourism-Management.pdf\" target=\"_blank\" rel=\"noopener\">B.Com &ndash; Travel &amp; Tourism<br />Management </a></li>\n<li><a href=\"https://mnwc.edu.in/uploads/3Programme-Specific-Outcome-PSO-B.Com-Accountancy-Specialization.pdf\" target=\"_blank\" rel=\"noopener\">B.Com &ndash; Accountancy </a></li>\n</ul>\n</div>\n</div>\n<!-- B.M.S -->\n<div class=\"col-md-4\">\n<div class=\"program-card h-100\">\n<h4 class=\"text-danger\">Bachelor of Management Studies (B.M.S)</h4>\n<h5 class=\"program-head\">Program Outcome</h5>\n<ul>\n<li><a href=\"https://mnwc.edu.in/uploads/Bachelors-of-Management-Studies-B.M.S.pdf\" target=\"_blank\" rel=\"noopener\">Bachelor of Management Studies </a></li>\n</ul>\n<h5 class=\"program-head\">Specific Outcome</h5>\n<ul>\n<li><a href=\"https://mnwc.edu.in/uploads/BMS-PSO.pdf\" target=\"_blank\" rel=\"noopener\">Bachelor of Management Studies </a></li>\n</ul>\n</div>\n</div>\n<!-- B.Com (AFI) -->\n<div class=\"col-md-4\">\n<div class=\"program-card h-100\">\n<h4 class=\"text-danger\">B.Com (With AFI)</h4>\n<h5 class=\"program-head\">Program Outcome</h5>\n<ul>\n<li><a href=\"https://mnwc.edu.in/uploads/Bachelors-of-Commerce-with-Accountancy-Finance-and-Insurance-B.Com-AFI.pdf\" target=\"_blank\" rel=\"noopener\">B.Com &ndash; Accountancy, Finance<br />&amp; Insurance </a></li>\n</ul>\n<h5 class=\"program-head\">Specific Outcome</h5>\n<ul>\n<li><a href=\"https://mnwc.edu.in/uploads/Programme-Specific-Outcome-PSO-Bachelors-of-Commerce-of-Accountancy-Finance-and-Insurance.pdf\" target=\"_blank\" rel=\"noopener\">B.Com &ndash; AFI </a></li>\n</ul>\n</div>\n</div>\n<!-- BAF -->\n<div class=\"col-md-4\">\n<div class=\"program-card h-100\">\n<h4 class=\"text-danger\">B.Com Accountancy &amp; Finance (BAF)</h4>\n<h5 class=\"program-head\">Program Outcome</h5>\n<ul>\n<li><a href=\"https://mnwc.edu.in/uploads/BAF-PO.pdf\" target=\"_blank\" rel=\"noopener\">B.Com &ndash; Accountancy &amp; Finance </a></li>\n</ul>\n<h5 class=\"program-head\">Specific Outcome</h5>\n<ul>\n<li><a href=\"https://mnwc.edu.in/uploads/BAF-PSO.pdf\" target=\"_blank\" rel=\"noopener\">B.Com &ndash; Accountancy &amp; Finance </a></li>\n</ul>\n</div>\n</div>\n<!-- B.Design -->\n<div class=\"col-md-4\">\n<div class=\"program-card h-100\">\n<h4 class=\"text-danger\">Bachelor of Design (B.Design)</h4>\n<h5 class=\"program-head\">Program Outcome</h5>\n<ul>\n<li><a href=\"https://mnwc.edu.in/uploads/B.DESIGN-OBJECTIVES-OUTCOMES.pdf\" target=\"_blank\" rel=\"noopener\">B.Design &ndash; Objectives &amp; Outcomes </a></li>\n</ul>\n<h5 class=\"program-head\">Specific Outcome</h5>\n<ul>\n<li><a href=\"https://mnwc.edu.in/uploads/B.DESIGN-OBJECTIVES-OUTCOMES-(1).pdf\" target=\"_blank\" rel=\"noopener\">B.Design &ndash; Specific Outcome </a></li>\n</ul>\n</div>\n</div>\n<!-- M.A -->\n<div class=\"col-md-4\">\n<div class=\"program-card h-100\">\n<h4 class=\"text-danger\">Masters of Arts (M.A)</h4>\n<h5 class=\"program-head\">Program Outcome</h5>\n<ul>\n<li><a href=\"https://mnwc.edu.in/uploads/Master-of-Arts-M.A.-Psychology.pdf\" target=\"_blank\" rel=\"noopener\">M.A &ndash; Psychology </a></li>\n</ul>\n<h5 class=\"program-head\">Specific Outcome</h5>\n<ul>\n<li><a href=\"https://mnwc.edu.in/uploads/1Programme-Specific-Outcome-PSO-M.A-With-Clinical-Psychology.pdf\" target=\"_blank\" rel=\"noopener\">M.A &ndash; Clinical Psychology </a></li>\n<li><a href=\"https://mnwc.edu.in/uploads/2Programme-Specific-Outcome-PSO-M.A-With-Counseling-Psychology.pdf\" target=\"_blank\" rel=\"noopener\">M.A &ndash; Counseling Psychology </a></li>\n</ul>\n</div>\n</div>\n<!-- M.Com -->\n<div class=\"col-md-4\">\n<div class=\"program-card h-100\">\n<h4 class=\"text-danger\">Masters of Commerce (M.Com)</h4>\n<h5 class=\"program-head\">Program Outcome</h5>\n<ul>\n<li><a href=\"https://mnwc.edu.in/uploads/Master-of-Commerce-M.Com_.pdf\" target=\"_blank\" rel=\"noopener\">Master of Commerce </a></li>\n</ul>\n<h5 class=\"program-head\">Specific Outcome</h5>\n<ul>\n<li><a href=\"https://mnwc.edu.in/uploads/1Programme-Specific-Outcome-PSO-M.Com-Advance-Management-Accounting-Auditing.pdf\" target=\"_blank\" rel=\"noopener\">M.Com &ndash; Advanced Management Accounting &amp; Auditing </a></li>\n<li><a href=\"https://mnwc.edu.in/uploads/2Programme-Specific-Outcome-PSO-M.Com-Human-Resource-Management.pdf\" target=\"_blank\" rel=\"noopener\">M.Com &ndash; Human Resource Management </a></li>\n</ul>\n</div>\n</div>\n<!-- PGECE -->\n<div class=\"col-md-4\">\n<div class=\"program-card h-100\">\n<h4 class=\"text-danger\">PGECE</h4>\n<h5 class=\"program-head\">Program Outcome</h5>\n<ul>\n<li><a href=\"https://mnwc.edu.in/uploads/PGECE-OBJECTIVES-OUTCOMES.pdf\" target=\"_blank\" rel=\"noopener\">Post Graduate Diploma in Early Childhood Education </a></li>\n</ul>\n<h5 class=\"program-head\">Specific Outcome</h5>\n<ul>\n<li><a href=\"https://mnwc.edu.in/uploads/PGECE-OBJECTIVES-OUTCOMES-(1).pdf\" target=\"_blank\" rel=\"noopener\">Post Graduate Diploma in Early Childhood Education </a></li>\n</ul>\n</div>\n</div>\n<!-- Bachelor of Science in Information Technology -->\n<div class=\"col-md-4\">\n<div class=\"program-card h-100\">\n<h4 class=\"text-danger\">Bachelor of Science in Information Technology (B.Sc.IT)</h4>\n<h5 class=\"program-head\">Program Outcome</h5>\n<h5 class=\"program-head\">Specific Outcome</h5>\n</div>\n</div>\n</div>', 'same_window', 'programs-outcomes', 'user_defined', 0, 'Programs Outcomes', '', '', 'Programs Outcomes', 1, NULL, 1, '', '1970-01-02', 279);
