(348, 'Quality Digest Newsletter', '', '<div class=\"table-responsive\">\n<table class=\"table table-bordered table-striped table-head-style\">\n<thead class=\"table-dark\">\n<tr>\n<th class=\"serial-width\">Sr. No.</th>\n<th class=\"text-start\">Title</th>\n<th class=\"document-heading-width\">Document</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td style=\"text-align: right;\">1</td>\n<td>Quality Digest Volume- 12</td>\n<td style=\"text-align: center;\"><a class=\"view-btn\" href=\"https://mnwc.edu.in/uploads/1QD-June-23-to-Mar-24.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">View</a></td>\n</tr>\n<tr>\n<td style=\"text-align: right;\">2</td>\n<td>Quality Digest Volume- 11</td>\n<td style=\"text-align: center;\"><a class=\"view-btn\" href=\"https://mnwc.edu.in/uploads/2QD-Nov-22-April-23.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">View</a></td>\n</tr>\n<tr>\n<td style=\"text-align: right;\">3</td>\n<td>Quality Digest Volume- 10</td>\n<td style=\"text-align: center;\"><a class=\"view-btn\" href=\"https://mnwc.edu.in/uploads/3Quality-Digest-2022-.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">View</a></td>\n</tr>\n<tr>\n<td style=\"text-align: right;\">4</td>\n<td>Quality Digest Volume- 9</td>\n<td style=\"text-align: center;\"><a class=\"view-btn\" href=\"https://mnwc.edu.in/uploads/4Quality-Digest-2020-2021.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">View</a></td>\n</tr>\n<tr>\n<td style=\"text-align: right;\">5</td>\n<td>Quality Digest Volume- 8</td>\n<td style=\"text-align: center;\"><a class=\"view-btn\" href=\"https://mnwc.edu.in/uploads/5Quality-Digest-2019-2020.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">View</a></td>\n</tr>\n<tr>\n<td style=\"text-align: right;\">6</td>\n<td>Quality Digest Volume- 7</td>\n<td style=\"text-align: center;\"><a class=\"view-btn\" href=\"https://mnwc.edu.in/uploads/7QD-Vol-6-Jan-2019.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">View</a></td>\n</tr>\n<tr>\n<td style=\"text-align: right;\">7</td>\n<td>Quality Digest Volume- 6</td>\n<td style=\"text-align: center;\"><a class=\"view-btn\" href=\"https://mnwc.edu.in/uploads/7QD-Vol-6-Jan-2019.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">View </a></td>\n</tr>\n<tr>\n<td style=\"text-align: right;\">8</td>\n<td>Quality Digest Volume- 5</td>\n<td style=\"text-align: center;\"><a class=\"view-btn\" href=\"https://mnwc.edu.in/uploads/8QD-Vol-5-Aug-2018.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">View</a></td>\n</tr>\n<tr>\n<td style=\"text-align: right;\">9</td>\n<td>Quality Digest Volume- 4</td>\n<td style=\"text-align: center;\"><a class=\"view-btn\" href=\"https://mnwc.edu.in/uploads/9QD-Vol-4-Apr-2018.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">View</a></td>\n</tr>\n<tr>\n<td style=\"text-align: right;\">10</td>\n<td>Quality Digest Volume- 3</td>\n<td style=\"text-align: center;\"><a class=\"view-btn\" href=\"https://mnwc.edu.in/uploads/10QD-Vol-3-Jan-2018.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">View </a></td>\n</tr>\n<tr>\n<td style=\"text-align: right;\">11</td>\n<td>Quality Digest Volume- 2</td>\n<td style=\"text-align: center;\"><a class=\"view-btn\" href=\"https://mnwc.edu.in/uploads/11QD-Vol-2-Aug-2017.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">View </a></td>\n</tr>\n<tr>\n<td style=\"text-align: right;\">12</td>\n<td>Quality Digest Volume- 1</td>\n<td style=\"text-align: center;\"><a class=\"view-btn\" href=\"https://mnwc.edu.in/uploads/12QD-Vol-1-Dec-2016.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">View </a></td>\n</tr>\n</tbody>\n</table>\n</div>', 'same_window', 'quality-digest-newsletter', 'user_defined', 0, 'Quality Digest Newsletter', '', '', 'Quality Digest Newsletter', 1, NULL, 1, '', '1970-01-02', 279),
(349, 'NORTH-EAST CELL', '', '<div class=\"north-east-cell\"><!-- North-East Cell -->\n<div class=\"mb-3\">\n<p class=\"text-justify inner-para\">Maniben Nanavati North-East Cell is established in the college in the year 2020. With the rise of racial discrimination against the people from North East region of India, MNNEC was formed to create a congenial atmosphere in which students from North East States feel safe and secure. In the last couple of years, there has been a growing increase in the number of students from North East enrolling in our college.</p>\n<p class=\"text-justify inner-para mt-2\">The cell is formed with a view to address issues and concerns of students from North-East states studying in the college, so as to ensure them a homely environment far away from home.</p>\n</div>\n<!-- Aims and Objectives -->\n<div class=\"mb-3\">\n<h5 class=\"section-title mt-3\">Aims and Objectives</h5>\n<ul class=\"styled-ol text-justify inner-para\">\n<li class=\"\">To promote the Spirit of Fraternity and Unity in Diversity as a step towards National Integration.</li>\n<li class=\"\">To work towards amalgamation of the lesser known cultures and traditions of students of North-East states into the mainstream.</li>\n<li class=\"\">To provide a platform for North and East students of the college to showcase and spread awareness about the diverse and magnificent cultures and traditions of North East states.</li>\n<li class=\"\">To ensure that any kind of discrimination and harassment is prevented.</li>\n<li class=\"\">To sensitize students on issues relating to security, cultural and linguistic concerns.</li>\n<li class=\"\">To sensitise the larger communities about issues faced by North East Students.</li>\n</ul>\n</div>\n<!-- Activities & Committee -->\n<div class=\"row\">\n<div class=\"col-md-12\">\n<h5 class=\"section-title mt-3\">Activities of the Cell</h5>\n<ul class=\"unstyled-ul \">\n<li class=\"\">Tourism Day</li>\n<li class=\"\">Seminars</li>\n<li class=\"\">Setting food stalls on special occasions</li>\n<li class=\"\">Student exchange</li>\n<li class=\"\">Traditional Performance</li>\n<li class=\"\">Literary Festivals</li>\n<li class=\"\">Visits</li>\n<li class=\"\">Exhibitions</li>\n</ul>\n</div>\n<div class=\"col-md-12\">\n<h5 class=\"section-title mt-3\">Committee Members</h5>\n<div class=\"table-responsive\">\n<table class=\"table table-bordered table-striped table-head-style\">\n<thead class=\"text-center\">\n<tr>\n<th class=\"text-center serial-width\">Sr. No.</th>\n<th class=\"text-start\">Designation</th>\n<th class=\"text-start\">Name</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td class=\"text-center\">1</td>\n<td>Principal</td>\n<td><strong>Dr. Rajshree Trivedi</strong></td>\n</tr>\n<tr>\n<td class=\"text-center\">2</td>\n<td>Nodal Officer for AICTE</td>\n<td><strong>Dr. Rita Patil</strong></td>\n</tr>\n<tr>\n<td class=\"text-center align-middle\" rowspan=\"4\">3</td>\n<td class=\"align-middle\" rowspan=\"4\">Member</td>\n<td><strong>Ms.Shraddha</strong></td>\n</tr>\n<tr>\n<td><strong>Ms. Vandana Keni</strong></td>\n</tr>\n<tr>\n<td><strong>Mr. Naresh Lad</strong></td>\n</tr>\n<tr>\n<td><strong>Ms. Annabel Rebello</strong></td>\n</tr>\n</tbody>\n</table>\n</div>\n</div>\n</div>\n<!-- Gallery -->\n<div class=\"mb-3\">\n<h5 class=\"section-title mt-3\">Gallery</h5>\n<div class=\"row g-3\">\n<div class=\"col-md-6 col-lg-4\"><a href=\"https://mnwc.edu.in/uploads/Culture-Display-768x1024.jpg\" data-lightbox=\"northeast\" data-title=\"Culture Display\"> <img class=\"img-fluid img-thumbnail\" src=\"https://mnwc.edu.in/uploads/Culture-Display-scaled-400x250.jpg\" alt=\"Culture Display\" /> </a></div>\n<div class=\"col-md-6 col-lg-4\"><a href=\"https://mnwc.edu.in/uploads/EDP-Workshop-1024x768.jpg\" data-lightbox=\"northeast\" data-title=\"EDP Workshop\"> <img class=\"img-fluid img-thumbnail\" src=\"https://mnwc.edu.in/uploads/EDP-Workshop-400x250.jpg\" alt=\"EDP Workshop\" /> </a></div>\n<div class=\"col-md-6 col-lg-4\"><a href=\"https://mnwc.edu.in/uploads/Food-Stall-1024x576.jpeg\" data-lightbox=\"northeast\" data-title=\"Food Stall\"> <img class=\"img-fluid img-thumbnail\" src=\"https://mnwc.edu.in/uploads/Food-Stall-400x250.jpeg\" alt=\"Food Stall\" /> </a></div>\n</div>\n</div>\n</div>', 'same_window', 'northeast-cell', 'user_defined', 0, '', '', '', 'NORTHEAST CELL', 1, NULL, 1, '', '1970-01-02', 235),
(350, 'PTA', '', '<div class=\"\"><!--Parent Teacher Association -->\n<div class=\"parent-teacher-association mb-2\">\n<h5 class=\"section-title\">Parent -Teacher Association</h5>\n<p class=\"text-justify inner-para\">The Parent Teacher Association (PTA), established in 2006, is a partnership between parents and teachers who strive to enhance students&rsquo; learning and enrich their lives within and outside the institution. It is also a forum for parents to obtain knowledge and voice their opinions about what is happening in the college. This is a platform where parents can share their ideas and share their valuable insights for the growth and development of the institution.</p>\n</div>\n<!-- Aims and Objectives Section -->\n<div class=\"row \">\n<div class=\"col-12\">\n<div class=\"\">\n<h2 class=\"title-subhead mt-2\">Aims and Objectives</h2>\n<ul class=\"styled-ol text-justify inner-para\">\n<li>To raise funds to help the institution provide extra resources for the students by bringing together parents and teachers and working towards a common goal.</li>\n<li>To run college events for parents and students; providing an opportunity for people to get to know each other and rejoice in each other\'s company.</li>\n<li>To encourage parents to become more involved with their children\'s institution and to develop strong links between home and the college.</li>\n<li>To provide support for college events and other special occasions.</li>\n</ul>\n</div>\n</div>\n</div>\n<!-- Accordion Section -->\n<div id=\"ptaAccordion\" class=\"accordion\"><!-- Composition of the PTA -->\n<div class=\"accordion-item\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#composition\" aria-expanded=\"true\" aria-controls=\"composition\"> Composition of the PTA </button></h2>\n<div id=\"composition\" class=\"accordion-collapse collapse show\" data-bs-parent=\"#ptaAccordion\">\n<div class=\"accordion-body\">\n<p class=\"text-justify inner-para\">The Parent Teachers Association of Maniben Nanavati College is a non-profit association, which is made up of College Staff and parents of the students.</p>\n<p class=\"text-justify inner-para\"><strong>The PTA Committee consists of &ndash;</strong><br />In-charge- <strong>Mrs. Prerna Ramteke.</strong><br />Co-In-charge- <strong> Nisarg Dave.</strong><br />Members- <strong>Ridhi Raut, Muktalata Jamatia, Ms. Amita Gaikwad and the elected parents </strong></p>\n<p class=\"text-justify inner-para\"><strong>How the Parents Become the Members of the PTA?</strong><br />Every year during the orientation program for the FY students, parents are invited to willingly become the members of the PTA. Interested parents fill up the form that is circulated to them at the end of the program to become the members of the Parent Teachers Association. The forms are printed in English, Hindi and Gujarati language so that it is easy for the parents to understand.<br />Various workshops are conducted for the parents every year. Parents are invited to the Orientation Program, Parent-Teachers Meeting during the FY result distribution; they are invited to the Scholarship program and the Farewell every year.</p>\n</div>\n</div>\n</div>\n<!-- Activities -->\n<div class=\"accordion-item\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#activities\" aria-expanded=\"false\" aria-controls=\"activities\"> Activities </button></h2>\n<div id=\"activities\" class=\"accordion-collapse collapse\" data-bs-parent=\"#ptaAccordion\">\n<div class=\"accordion-body\">\n<p class=\"text-justify inner-para\">The following activities are organised as part of the Parent-Teacher Association:</p>\n<ul class=\"unstyled-ul inner-para text-justify\">\n<li>The discussion of a student\'s performance in the academic year on the day of the Result distribution.</li>\n<li>Workshop on Clean Mumbai, Green Mumbai.</li>\n<li>Organize Orientation Program for parents and make them aware about college activities.</li>\n<li>Inviting the parents of the toppers on the day of result distribution.</li>\n<li>PTA members involvement on the Annual day.</li>\n</ul>\n</div>\n</div>\n</div>\n<!-- Projects by PTA -->\n<div class=\"accordion-item\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#projects\" aria-expanded=\"false\" aria-controls=\"projects\"> Projects by PTA </button></h2>\n<div id=\"projects\" class=\"accordion-collapse collapse\" data-bs-parent=\"#ptaAccordion\">\n<div class=\"accordion-body\">\n<h2 class=\"title-subhead mt-2\">Project SAAJHEDAARI sponsored by Anugrah Charitable Society</h2>\n<ul class=\"unstyled-ul inner-para text-justify\">\n<li class=\"\"><strong>\'Carry Your Own Bag\'</strong>: \"Use your talent in any way you can, don\'t keep it for yourself like a miser spend it like a millionaire\". PTA involved parents in the mission to create eco-friendly cloth bags that were valuable alternative to plastic bags. So, the mother volunteers made cloth bags for which material was provided by the PTA.</li>\n<li class=\"\"><strong>Parents Day Out</strong>: \"Do your best there is no such thing as a perfect parent\" PTA encouraged students to give their parents the \'free time\' to enroll for the following training opportunities:<br /><strong>a) </strong>PTA invited teachers/experts to provide training to parents in their areas of interest to help them to upgrade their skills and expand their knowledge horizons.<br /><strong>b) </strong>Four sessions of training were conducted for by eminent Psychologist Ms. Srilata Shrikant, Prafulata Psychological Services, Andheri (East).</li>\n</ul>\n<h2 class=\"title-subhead mt-2\">Intergenerational Bonding between Grandparents and Children</h2>\n<p class=\"text-justify inner-para\">One Day Sensitization Program on \'Intergenerational Bonding between Grandparents and Children was organized on Tuesday, 30th October 2018. 68 Parents 88 Students in total attended the event. This program was sponsored by The Ministry of Social Justice and Empowerment, Govt. of India, National Institute of Social Defence (NISD), Centre for the Study of Social Change (CCSC), and Regional Resource Training Centre (RRTC) in association with Bharat Vikas Parishad, Powai Chandiwali branch.<br />The resource persons for the event were Advocate Nirmala Samant Prabhawalkar, Mr. Prakash Borgaonkar, President of Help Age India and Mrs. Neelam Potdar, Coordinator of Bharat Vikas Parishad, Founder of Saksham digital empowerment program.</p>\n</div>\n</div>\n</div>\n<!-- Gallery -->\n<div class=\"accordion-item\">\n<h2 class=\"accordion-header\"><button class=\"accordion-button collapsed\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#gallery\" aria-expanded=\"false\" aria-controls=\"gallery\"> Gallery </button></h2>\n<div id=\"gallery\" class=\"accordion-collapse collapse\" data-bs-parent=\"#ptaAccordion\">\n<div class=\"accordion-body\">\n<div class=\"row g-3\">\n<div class=\"col-md-4 col-sm-6\"><a href=\"https://mnwc.edu.in/uploads/Talk-on-Prevention-of-Cervical-Cancer-and-Vaccine-1024x768.jpg\" data-lightbox=\"pta\" data-title=\"Talk on Prevention of Cervical Cancer and Vaccine\"> <img class=\"img-fluid img-thumbnail\" src=\"https://mnwc.edu.in/uploads/Talk-on-Prevention-of-Cervical-Cancer-and-Vaccine-400x250.jpg\" alt=\"Talk on Prevention of Cervical Cancer and Vaccine\" /> </a></div>\n<div class=\"col-md-4 col-sm-6\"><a href=\"https://mnwc.edu.in/uploads/Talk-on-NEP-2020-by-Vinaya-Vaishampayan-400x250.jpg\" data-lightbox=\"pta\" data-title=\"Talk on NEP-2020 by Vinaya Vaishampayan \"> <img class=\"img-fluid img-thumbnail\" src=\"https://mnwc.edu.in/uploads/Talk-on-NEP-2020-by-Vinaya-Vaishampayan-400x250.jpg\" alt=\"Talk on NEP-2020 by Vinaya Vaishampayan \" /> </a></div>\n<div class=\"col-md-4 col-sm-6 \"><a href=\"https://mnwc.edu.in/uploads/Annual-Prize-Distribution-Function-400x250.jpg\" data-lightbox=\"pta\" data-title=\"Parents Registration Counter\"> <img class=\"img-fluid img-thumbnail\" src=\"https://mnwc.edu.in/uploads/Annual-Prize-Distribution-Function-400x250.jpg\" alt=\"Annual Prize Distribution Function \" /> </a></div>\n<div class=\"col-md-4 col-sm-6 \"><a href=\"https://mnwc.edu.in/uploads/Parents-Registration-Counter-400x250.jpg\" data-lightbox=\"pta\" data-title=\"Image 1\"> <img class=\"img-fluid img-thumbnail \" src=\"https://mnwc.edu.in/uploads/Parents-Registration-Counter-400x250.jpg\" alt=\"Parents Registration Counter \" /> </a></div>\n<div class=\"col-md-4 col-sm-6 \"><a href=\"https://mnwc.edu.in/uploads/Blood-Donation-Camp-in-collaboration-with-Youth-Red-Cross1-400x250.png\" data-lightbox=\"pta\" data-title=\"Blood Donation Camp in collaboration with\n                                    Youth Red Cross\"> <img class=\"img-fluid img-thumbnail \" src=\"https://mnwc.edu.in/uploads/Blood-Donation-Camp-in-collaboration-with-Youth-Red-Cross1-400x250.png\" alt=\"Blood Donation Camp in collaboration with\n                                    Youth Red Cross \" /> </a></div>\n<div class=\"col-md-4 col-sm-6 \"><a href=\"https://mnwc.edu.in/uploads/Inauguration-of-Project-Green-Campus-400x250.jpg\" data-lightbox=\"pta\" data-title=\"Inauguration of Project Green Campus\"> <img class=\"img-fluid img-thumbnail \" src=\"https://mnwc.edu.in/uploads/Inauguration-of-Project-Green-Campus-400x250.jpg\" alt=\"Inauguration of Project Green Campus \" /> </a></div>\n<div class=\"col-md-4 col-sm-6 \"><a href=\"https://mnwc.edu.in/uploads/Online-talk-by-Shubhajeet-Mukherjee-Mission-Green-Mumbai-400x250.png\" data-lightbox=\"pta\" data-title=\"Online talk by Shubhajeet Mukherjee, Mission\n                                    Green Mumbai \"> <img class=\"img-fluid img-thumbnail\" src=\"https://mnwc.edu.in/uploads/Online-talk-by-Shubhajeet-Mukherjee-Mission-Green-Mumbai-400x250.png\" alt=\"Online talk by Shubhajeet Mukherjee, Mission\n                                    Green Mumbai \" /> </a></div>\n</div>\n</div>\n</div>\n</div>\n</div>\n</div>', 'same_window', 'pta', 'user_defined', 0, '', '', '', 'PTA', 1, NULL, 1, '', '1970-01-02', 2),
(351, 'Divyangjan Cell', '', '<div class=\"\"><!-- Description Section -->\n<div class=\"row mb-2\">\n<div class=\"col-12\">\n<p class=\"inner-para text-justify\">Divyangjan Cell of Maniben Nanavati Women\'s College is established with an objective of empowerment of students with disabilities (Divyangjan, connoted as divine body). This cell conducts programs to create awareness and accept diversity as a part of human existence in its institutional practices. It further enables the atmosphere of respect and preserves the identities of the Divyangjan students. This cell facilitates teachers with knowledge and skills of using various aids and appliances required to cater needs of differently abled students. It further makes teaching more inclusive and cognizant for the Divyangjan students. This cell also looks after the physical infrastructure and availing resources as par the special needs of the students.</p>\n</div>\n</div>\n<!-- Objectives and Support Areas Section -->\n<div class=\"row\"><!-- Objectives Column -->\n<div class=\"col-md-6\">\n<div class=\"\">\n<h5 class=\"section-title mt-3\">Objectives</h5>\n<ul class=\"unstyled-ul\">\n<li class=\"\">To ease out admission process for Divyangjan students</li>\n<li class=\"\">To create awareness and sensitize about varied needs of Divyanjan among teachers and students</li>\n<li class=\"\">To augment learning experience for students with special needs with inclusive practices</li>\n<li class=\"\">To provide guidance and counselling as par their specific requirements</li>\n<li class=\"\">To celebrate importance days like world disability day, conducting workshop to sensitize society about capabilities of Divyangjan</li>\n<li class=\"\">To deliver support for the concessions and facilities meant for Divyangjan in accordance with PWD Act, 2016 under NEP 2020</li>\n<li class=\"\">To assist Divyangjan students for self-sustenance and employment</li>\n</ul>\n</div>\n</div>\n<!-- Support Areas Column -->\n<div class=\"col-md-6\">\n<h5 class=\"section-title mt-3\">Support areas offered by college</h5>\n<ul class=\"unstyled-ul\">\n<li>Ramp</li>\n<li>Lift</li>\n<li>Railing on staircases</li>\n<li>Wheel chair</li>\n<li>Disable friendly washroom</li>\n<li>Braille books in library</li>\n<li>Writers for students with learning disability</li>\n<li>Counsellors</li>\n<li>Allocation of extra time in college examinations for LD students</li>\n<li>Remedial teaching for LD students</li>\n<li>Workshops sensitizing the needs of the divyangjans</li>\n</ul>\n</div>\n</div>\n<!-- Gallery Section -->\n<div class=\"row\">\n<div class=\"col-12\">\n<h5 class=\"section-title mt-3\">Gallery</h5>\n<div class=\"row g-3\">\n<div class=\"col-md-6 col-12 col-lg-3\"><a href=\"https://mnwc.edu.in/uploads/Disability-Day-300x225.jpg\" target=\"_blank\" rel=\"noopener\" data-lightbox=\"Divyangjan-gallery\" data-title=\"img-1\"> <img class=\"img-fluid img-thumbnail rounded\" src=\"https://mnwc.edu.in/uploads/Disability-Day-300x225.jpg\" alt=\"Disability Day\" /> </a></div>\n<div class=\"col-md-6 col-12 col-lg-3\"><a href=\"https://mnwc.edu.in/uploads/Being-Different-is-Beautiful-Skit-300x225.jpg\" target=\"_blank\" rel=\"noopener\" data-lightbox=\"Divyangjan-gallery\" data-title=\"img-2\"> <img class=\"img-fluid img-thumbnail rounded\" src=\"https://mnwc.edu.in/uploads/Being-Different-is-Beautiful-Skit-300x225.jpg\" alt=\"Being Different is Beautiful\" /> </a></div>\n<div class=\"col-md-6 col-12 col-lg-3\"><a href=\"https://mnwc.edu.in/uploads/Being-Different-is-Beautiful-300x225.jpg\" target=\"_blank\" rel=\"noopener\" data-lightbox=\"Divyangjan-gallery\" data-title=\"img-3\"> <img class=\"img-fluid img-thumbnail rounded\" src=\"https://mnwc.edu.in/uploads/Being-Different-is-Beautiful-300x225.jpg\" alt=\"Being Different is Beautiful Skit\" /> </a></div>\n<div class=\"col-md-6 col-12 col-lg-3\"><a href=\"https://mnwc.edu.in/uploads/Socio-Emotional-Skills-Workshop-300x225.jpg\" target=\"_blank\" rel=\"noopener\" data-lightbox=\"Divyangjan-gallery\" data-title=\"img4\"> <img class=\"img-fluid img-thumbnail rounded\" src=\"https://mnwc.edu.in/uploads/Socio-Emotional-Skills-Workshop-300x225.jpg\" alt=\"Socio Emotional Skills Workshop\" /> </a></div>\n</div>\n</div>\n</div>\n</div>', 'same_window', 'divyangjan-cell', 'user_defined', 0, '', '', '', 'Divyangjan Cell', 1, NULL, 1, '', '1970-01-02', 235);
