(407, 'Our Voice', '', '<div class=\"container py-5\">\n<div class=\"row unified-layout\"><!-- Desktop Sidebar (Hidden on Mobile) -->\n<div class=\"col-lg-3 nav-pills-desktop\">\n<div id=\"v-pills-tab\" class=\"nav flex-column nav-pills\" role=\"tablist\"><button id=\"v-tab-publication\" class=\"nav-link active\" role=\"tab\" type=\"button\" data-bs-toggle=\"pill\" data-bs-target=\"#pane-publication\">Our Publication</button> <button id=\"v-tab-raah\" class=\"nav-link\" role=\"tab\" type=\"button\" data-bs-toggle=\"pill\" data-bs-target=\"#pane-raah\">RAAH &ndash; Transgender Community</button></div>\n</div>\n<!-- Content Area (Shared Sidebar/Accordion) -->\n<div id=\"unified-accordion\" class=\"col-lg-9 tab-content accordion\"><!-- 1. Our Publication Section -->\n<div id=\"pane-publication\" class=\"tab-pane fade show active accordion-item\" role=\"tabpanel\">\n<h2 class=\"accordion-header accordion-header-mobile\"><button class=\"accordion-button\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#collapseOne\"> Our Publication </button></h2>\n<div id=\"collapseOne\" class=\"accordion-collapse collapse show\" data-bs-parent=\"#unified-accordion\">\n<div class=\"accordion-body\">\n<h2 class=\"sub-head sub-head-desktop\">Our Publication</h2>\n<h5 class=\"section-title\">Books:</h5>\n<ul class=\"unstyled-ul\">\n<li><strong>Gandhiji Book</strong> <a href=\"https://mnwc.edu.in/wp-content/uploads/2020/11/IMG-20201031-WA0012.jpg\" target=\"_blank\" rel=\"noopener\">View Book</a></li>\n<li><strong>Digital Humanities</strong> <a href=\"https://mnwc.edu.in/wp-content/uploads/2020/11/tempFileForShare_20201031-2204381.jpg\" target=\"_blank\" rel=\"noopener\">View Publication</a></li>\n</ul>\n<h5 class=\"section-title\">Magazines:</h5>\n<ul class=\"unstyled-ul\">\n<li><strong>Srishti</strong> <a href=\"https://drive.google.com/file/d/1VmOe4gI4dxR0aqvnIYD_f0TFQx_yjSKA/view?usp=drivesdk\" target=\"_blank\" rel=\"noopener\">Srishti 2021</a></li>\n<li><strong>Shanelle</strong> <a href=\"https://mnwc.edu.in/uploads/SHANELLE_28_1_2021_FINAL_SINGLE-PAGES.pdf\" target=\"_blank\" rel=\"noopener\">Shanelle the Chic Way 2021</a></li>\n</ul>\n<h5 class=\"section-title\">Newsletters: Campus Breeze</h5>\n<div class=\"table-responsive\">\n<table class=\"table custom-table align-middle\">\n<thead>\n<tr>\n<th class=\"text-center\" width=\"80\">Sr. No.</th>\n<th>Title</th>\n<th class=\"text-center\" width=\"120\">Document</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td class=\"text-center\">1</td>\n<td>CAMPUS BREEZE September &ndash; 2019</td>\n<td class=\"text-center\"><a class=\"view-btn\" href=\"https://mnwc.edu.in/uploads/1CAMPUS-BREEZE_september-2019-issue1.pdf\" target=\"_blank\" rel=\"noopener\">View</a></td>\n</tr>\n<tr>\n<td class=\"text-center\">2</td>\n<td>CAMPUS BREEZE February &ndash; 2020</td>\n<td class=\"text-center\"><a class=\"view-btn\" href=\"https://mnwc.edu.in/uploads/2CAMPUS-BREEZE-Feb-2020-11.pdf\" target=\"_blank\" rel=\"noopener\">View</a></td>\n</tr>\n</tbody>\n</table>\n</div>\n<div class=\"row g-3 mt-3\">\n<div class=\"col-md-6\"><a class=\"btn-pdf\" href=\"https://mnwc.edu.in/quality-digest-newsletter\" target=\"_blank\" rel=\"noopener\">Quality Digest IQAC Newsletter</a></div>\n<div class=\"col-md-6\"><a class=\"btn-pdf\" href=\"#\" target=\"_blank\" rel=\"noopener\">SUMANAA Alumni Newsletter</a></div>\n</div>\n</div>\n</div>\n</div>\n<!-- 2. RAAH Section -->\n<div id=\"pane-raah\" class=\"tab-pane fade accordion-item\" role=\"tabpanel\">\n<h2 class=\"accordion-header accordion-header-mobile\"><button class=\"accordion-button collapsed\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#collapseTwo\"> RAAH &ndash; Transgender Community </button></h2>\n<div id=\"collapseTwo\" class=\"accordion-collapse collapse\" data-bs-parent=\"#unified-accordion\">\n<div class=\"accordion-body\">\n<h2 class=\"sub-head sub-head-desktop\">RAAH &ndash; Website for Transgender Community</h2>\n<div class=\"raah-link\"><img src=\"https://mnwc.edu.in/uploads/RAAh.png\" alt=\"RAAH Logo\" />\n<div>\n<p class=\"mb-3\"><strong>To Visit Website &ndash;</strong></p>\n<a class=\"view-btn\" href=\"http://raah.mnwc.edu.in/\" target=\"_blank\" rel=\"noopener\">CLICK HERE TO VISIT</a></div>\n</div>\n</div>\n</div>\n</div>\n</div>\n</div>\n</div>', 'same_window', 'our-voice', 'user_defined', 0, 'Our Voice', '', '', 'Our Voice', 1, NULL, 1, '', '1970-01-02', 2),
