(471, 'Centre for Holistic Education, Training and Novel Advancement (CHETNA)', '', '<div class=\"row\"><!-- LEFT SIDE TABS (Desktop Only) -->\n<div class=\"col-lg-3 nav-pills-desktop\">\n<div id=\"v-pills-tab\" class=\"nav flex-column nav-pills\" role=\"tablist\"><button class=\"nav-link active\" data-bs-toggle=\"pill\" data-bs-target=\"#about\"> About Chetna </button> <button class=\"nav-link\" data-bs-toggle=\"pill\" data-bs-target=\"#vision\"> Vision </button> <button class=\"nav-link\" data-bs-toggle=\"pill\" data-bs-target=\"#mission\"> Mission </button> <button class=\"nav-link\" data-bs-toggle=\"pill\" data-bs-target=\"#co\"> Course Offered </button> <button class=\"nav-link\" data-bs-toggle=\"pill\" data-bs-target=\"#brochure\"> Brochure</button> <button class=\"nav-link\" data-bs-toggle=\"pill\" data-bs-target=\"#reports\"> Gallery </button></div>\n</div>\n<!-- RIGHT SIDE CONTENT (Shared between Mobile & Desktop) -->\n<div class=\"col-lg-9\">\n<div id=\"unified-accordion\" class=\"tab-content accordion\"><!--1-->\n<div id=\"about\" class=\"tab-pane fade accordion-item border-0 active show\" role=\"tabpanel\">\n<h2 class=\"accordion-header accordion-header-mobile\"><button class=\"accordion-button\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#collapseAbout\"> About Chetna </button></h2>\n<div id=\"collapseAbout\" class=\"accordion-collapse collapse show\" data-bs-parent=\"#unified-accordion\">\n<div class=\"accordion-body principal-wrapper p-0 pt-lg-0\"><!-- <h2 class=\"sub-head sub-head-desktop\">INTRODUCTION TO THE INSTITUTION:</h2> -->\n<p class=\"mt-3 mb-3\"><img class=\"img-fluid\" src=\"https://mnwc.edu.in/wp-content/uploads/2024/12/0002.png\" alt=\"CHETNA\" /></p>\n<p class=\"mt-3 mb-3\"><img class=\"img-fluid\" src=\"https://mnwc.edu.in/wp-content/uploads/2024/12/0005.png\" alt=\"CHETNA\" /></p>\n</div>\n</div>\n</div>\n<!--2-->\n<div id=\"vision\" class=\"tab-pane fade accordion-item border-0\" role=\"tabpanel\">\n<h2 class=\"accordion-header accordion-header-mobile\"><button class=\"accordion-button collapsed\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#collapseVision\"> Vision </button></h2>\n<div id=\"collapseVision\" class=\"accordion-collapse collapse show\" data-bs-parent=\"#unified-accordion\">\n<div class=\"accordion-body principal-wrapper p-0 pt-lg-0\"><!-- <h2 class=\"sub-head sub-head-desktop\">Research Horizon</h2> -->\n<p class=\"mt-3 mb-3\"><img class=\"img-fluid\" src=\"https://mnwc.edu.in/wp-content/uploads/2024/12/0003.png\" alt=\"CHETNA\" /></p>\n</div>\n</div>\n</div>\n<!--3-->\n<div id=\"mission\" class=\"tab-pane fade accordion-item border-0\" role=\"tabpanel\">\n<h2 class=\"accordion-header accordion-header-mobile\"><button class=\"accordion-button collapsed\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#collapseMission\"> Mission </button></h2>\n<div id=\"collapseMission\" class=\"accordion-collapse collapse show\" data-bs-parent=\"#unified-accordion\">\n<div class=\"accordion-body principal-wrapper p-0 pt-lg-0\">\n<p class=\"mt-3 mb-3\"><img class=\"img-fluid\" src=\"https://mnwc.edu.in/wp-content/uploads/2024/12/0004.png\" alt=\"CHETNA\" /></p>\n</div>\n</div>\n</div>\n<!--4-->\n<div id=\"co\" class=\"tab-pane fade accordion-item border-0\" role=\"tabpanel\">\n<h2 class=\"accordion-header accordion-header-mobile\"><button class=\"accordion-button collapsed\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#collapseCo\"> Course Offered </button></h2>\n<div id=\"collapseCo\" class=\"accordion-collapse collapse show\" data-bs-parent=\"#unified-accordion\">\n<div class=\"accordion-body principal-wrapper p-0 pt-lg-0\">\n<table class=\"table table-bordered table-condenced\">\n<thead>\n<tr class=\"bg-primary\">\n<th>Sr. No.</th>\n<th>Title</th>\n<th>Document</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>1.</td>\n<td>2023-24</td>\n<td><a class=\"btn btn-warning\" href=\"https://mnwc.edu.in/wp-content/uploads/2024/12/4.1_CHETNA_Courses-Offered_23-24.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">View </a></td>\n</tr>\n<tr>\n<td>2.</td>\n<td>2024-25</td>\n<td><a class=\"btn btn-warning\" href=\"https://mnwc.edu.in/wp-content/uploads/2024/12/4.2_CHETNA_Courses-Offered_24-25.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">View </a></td>\n</tr>\n<tr>\n<td>3.</td>\n<td>Other Courses</td>\n<td><a class=\"btn btn-warning\" href=\"https://mnwc.edu.in/wp-content/uploads/2024/12/4.3_CHETNA_Other-Courses.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">View </a></td>\n</tr>\n</tbody>\n</table>\n</div>\n</div>\n</div>\n<!--5-->\n<div id=\"brochure\" class=\"tab-pane fade accordion-item border-0\" role=\"tabpanel\">\n<h2 class=\"accordion-header accordion-header-mobile\"><button class=\"accordion-button collapsed\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#collapseBrochure\"> Brochure </button></h2>\n<div id=\"collapseBrochure\" class=\"accordion-collapse collapse show\" data-bs-parent=\"#unified-accordion\">\n<div class=\"accordion-body principal-wrapper p-0 pt-lg-0\">\n<div class=\"row\">\n<div class=\"col-md-4 mt-3 mb-3\"><img class=\"img-fluid\" src=\"https://mnwc.edu.in/wp-content/uploads/2024/11/BD-BROCHURE.jpeg\" alt=\"CHETNA\" /></div>\n<div class=\"col-md-4 mt-3 mb-3\"><img class=\"img-fluid\" src=\"https://mnwc.edu.in/wp-content/uploads/2024/11/Bcom-brochure.jpeg\" alt=\"CHETNA\" /></div>\n<div class=\"col-md-4 mt-3 mb-3\"><img class=\"img-fluid\" src=\"https://mnwc.edu.in/wp-content/uploads/2024/11/MCOM-BROCHURE.jpg\" alt=\"CHETNA\" /></div>\n<div class=\"col-md-4 mt-3 mb-3\"><img class=\"img-fluid\" src=\"https://mnwc.edu.in/wp-content/uploads/2024/11/Brochure-With-Archana-pic.jpeg\" alt=\"CHETNA\" /></div>\n<div class=\"col-md-4 mt-3 mb-3\"><img class=\"img-fluid\" src=\"https://mnwc.edu.in/wp-content/uploads/2024/11/Chetna_Brochure-724x1024.jpeg\" alt=\"CHETNA\" /></div>\n</div>\n</div>\n</div>\n</div>\n<!--6-->\n<div id=\"reports\" class=\"tab-pane fade accordion-item border-0\" role=\"tabpanel\">\n<h2 class=\"accordion-header accordion-header-mobile\"><button class=\"accordion-button collapsed\" type=\"button\" data-bs-toggle=\"collapse\" data-bs-target=\"#collapseReports\"> Gallery </button></h2>\n<div id=\"collapseReports\" class=\"accordion-collapse collapse show\" data-bs-parent=\"#unified-accordion\">\n<div class=\"accordion-body principal-wrapper p-0 pt-lg-0\">\n<h2 class=\"sub-head sub-head-desktop\">Gallery</h2>\n<p class=\"inner-para text-justify\">&nbsp;</p>\n</div>\n</div>\n</div>\n</div>\n</div>\n</div>', 'same_window', 'centre-for-holistic-education-training-and-novel-advancement-chetna', 'user_defined', 0, '', '', '', 'Centre for Holistic Education Training and Novel Advancement CHETNA', 1, NULL, 1, '', '0000-00-00', 2);
