INSERT INTO `tbl_section_info` (`dsi_id`, `dsi_dsm_id`, `dsi_dsl_id`, `dsi_asl_id`, `dsi_ayl_id`, `dsi_assl_id`, `dsi_lib_id`, `dsi_res_id`, `dsi_new_content`, `dsi_content`, `dsi_is_display_on_website`, `approve_bit`, `rejected_reason`, `dsm_order`, `dsi_user_id`, `dsi_time`) VALUES
(378, 1, 16, NULL, NULL, NULL, NULL, NULL, '', '<p><span style=\"font-weight: 400;\">The Bachelor&rsquo;s in Textile and Fashion Design is a comprehensive three -year undergraduate programme tailored for creative individuals looking to build a career in the global Fashion and textile industry. Spanning six semesters, the course strikes a balance between artistic expression, technical proficiency, and commercial viability. Study from Fibre &gt; Fabric &gt; Pattern Making &gt; Garment Construction &gt; Styling &gt; Fashion Show &gt; Branding/ Marketing and so much more.</span></p>\n<p>Maniben Nanavati Women&rsquo;s College known as the best&nbsp;<strong>fashion designing college in Mumbai</strong>&nbsp;because of our:</p>\n<ul class=\"unstyled-ul\">\n<li>Highly Qualified Teaching Faculty</li>\n<li>High-tech Computer Lab for CAD etc.</li>\n<li>Pattern Making Lab</li>\n<li>Garment Construction Lab</li>\n<li>Art and Design Room</li>\n<li>Smart Classrooms for virtual learning and visits</li>\n<li>Air Conditioned Seminar Hall</li>\n<li>Amphitheatre</li>\n</ul>\n<p class=\"mt-2\">As a&nbsp;<strong>bachelor&rsquo;s in fashion design college</strong>, we believe in giving students industry exposure through guest lectures, industrial visits, and internships. Fashion Celebrities who visit our college:</p>\n<ul class=\"unstyled-ul\">\n<li><strong>Jay Lapasia</strong></li>\n<li><strong>Anuj Sharma</strong></li>\n<li><strong>Gurleen Arora</strong></li>\n<li><strong>Binal Shah</strong></li>\n<li><strong>Dipti Bharwani</strong></li>\n<li><strong>Tanisha Nanavati</strong><strong>&nbsp;and many more</strong></li>\n</ul>\n<p class=\"mt-2\"><strong>Topics Covered in Curriculum :</strong><br />Pattern Making, Garment Construction, Fashion Designing, Fashion Merchandising, Fashion Retailing, Textile Design, Fashion Styling, Fashion Communication, Fashion Journalist, Fashion Consultancy and much more.</p>\n<p class=\"mt-2\"><strong>Hands on Experience in:</strong><br />Women&rsquo;s Wear, Men&rsquo;s Wear, Haute couture, Red Carpet Ensembles &amp; Outfits, Indian Wear, Ethnic Wear, Kids Wear, Casual Wear, Corporate Wear, Beach Wear, Party Wear and others</p>\n<p class=\"mt-2\"><strong>Special Training in:</strong><br />Case studies, Portfolio Making, Fashion Presentation, Fashion Projects and others.</p>\n<p class=\"mt-2\"><strong>Visits&nbsp;</strong>&nbsp;to branded Fashion Houses and Hubs, Textile industries, Export houses, Garment manufacturing units, Dyeing &amp; Printing houses, Embroidery units and Retail Houses.</p>\n<p class=\"mt-2\"><strong>Workshops on Fashions</strong>&nbsp;at MNWC include &nbsp;Color Scheme and Fabric Study, Wardrobe Management, Introduction to Fashion Art &amp; Style, Cycle of Fashions, Art Appreciation, Shibori Painting, Color Theory- Costume Designers and their point of view, Personal Styling and much more.</p>\n<p class=\"mt-2\">We are a 50 year old&nbsp;<span style=\"text-decoration: underline; color: #3598db;\"><a style=\"color: #3598db; text-decoration: underline;\" href=\"https://mnwc.edu.in/home\"><strong>women&rsquo;s college in Mumbai</strong>,</a>&nbsp;</span> We also offer &nbsp;<a href=\"https://mnwc.edu.in/customer-relationship-management-crm-courses-in-mumbai\"><span style=\"text-decoration: underline; color: #3598db;\"><strong>customer relationship management course</strong></span>,</a>&nbsp;hospital &amp; healthcare management course, and Event &amp; media management course,&nbsp;<span style=\"color: #3598db;\"><a style=\"color: #3598db;\" href=\"https://mnwc.edu.in/tourism-and-travel-management-ttm-course\"><strong>t<span style=\"text-decoration: underline;\">ravel &amp; tourism course</span></strong></a><span style=\"text-decoration: underline;\">.</span></span></p>\n<p class=\"mt-2\"><span style=\"text-decoration: underline; color: #3598db;\"><a style=\"color: #3598db; text-decoration: underline;\" href=\"https://mnwc.edu.in/department/11/MA-Psycology#!/11/ma-psycology?sectionId=95\"><strong>MA psychology colleges in Mumbai</strong>.</a></span><br />We have students from all over Maharashtra applying for the MA Psychology program at our institute. All of our courses are accessible for enrollment at our&nbsp;<strong>women&rsquo;s college</strong>&nbsp;through the completion of an&nbsp;<strong>online admission</strong>&nbsp;form available on the SNDT University website.</p>\n<p class=\"mt-2\"><strong>Maniben Nanavati Women&rsquo;s College is one of the Best Colleges in Mumbai for Fashion Designing.</strong></p>\n<p class=\"mt-2\">Step into Maniben Nanavati Women&rsquo;s College and experience the exotic world of Fashions at our State- of- the -Art &nbsp;Fashion Lab.</p>\n<div class=\"row\">\n<div class=\"col-md-4\"><a class=\"btn-pdf\" href=\"https://mnwc.edu.in/wp-content/uploads/2024/12/B.Des-Brochure.pdf\" target=\"_blank\" rel=\"noopener\"> <span class=\"btn-text\">Bachelor of Fashion Design Colleges in Mumbai </span> </a></div>\n<div class=\"col-md-4\"><a class=\"btn-pdf\" href=\"https://mnwc.edu.in/wp-content/uploads/2024/11/SHANELLE-MNWC.pdf\" target=\"_blank\" rel=\"noopener\"> <span class=\"btn-text\">Shanelle Design Magazine</span> </a></div>\n</div>', '1', 1, '', 0, 2, '2026-03-23 00:00:00'),
